  ],
  "analysis": [
    {
      "clause_id": "§1",
      "question_id": "Q1",
      "answer": "Compared to current law, where each county decides whether to honor federal immigration detainers, this measure mandates that every county jail honor them and hold the specified individuals for up to 48 hours past their normal release time.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q2",
      "answer": "County jails will incur direct costs to house, feed, and secure individuals for up to an additional 48 hours. Opportunity costs include occupying jail beds and staff time that could otherwise be used for other local purposes.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q3",
      "answer": "County governments bear the direct costs of the extended detention. Federal immigration authorities benefit from guaranteed local cooperation and improved access to the individuals they are seeking.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q4",
      "answer": "Counties that currently do not honor detainers will be forced to change their jail policies. Knowing they could be detained for immigration authorities, unauthorized immigrants might become less likely to interact with local law enforcement or use public services out of fear of deportation.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q5",
      "answer": "The measure addresses the lack of uniform cooperation with federal immigration authorities across counties. By removing local discretion, it eliminates policies that limit local cooperation with immigration enforcement, though doing so may create a chilling effect on immigrant interaction with local government.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q6",
      "answer": "Federal immigration authorities gain the power to compel local jails to hold individuals. State government asserts authority over county jail policies, reducing the discretionary power of local sheriffs and county governments.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q7",
      "answer": "The effect of local law enforcement cooperating with federal immigration authorities on community safety is empirically disputed. Some researchers find that such cooperation removes offenders and deters crime, while others find it discourages immigrant communities from reporting crimes and acting as witnesses, potentially making communities less safe.",
      "disputed": true
    },
    {
      "clause_id": "§1",
      "question_id": "Q9",
      "answer": "The measure can be undone by a subsequent legislative act or ballot measure, depending on whether it is enacted as a statute or a constitutional amendment.",
      "disputed": false
    }
  ],
